    qa: [
      { q: 'What happens if a screw is turned too impatiently?', choices: ['The wood begins to grow soft and weak', 'The head of the screw is damaged', 'The handle breaks away from the blade', 'The hinge falls off the door at once'], answer: 1, why: '第2段落 If the turning is too impatient, the head of the screw is damaged。' },
      { q: 'What did the writer\'s grandfather say about screws?', choices: ['They should always be turned quickly', 'They are stronger than nails or glue', 'They should be firm, not defeated', 'They should be bought only in pairs'], answer: 2, why: '第6段落 a screw should be firm, not defeated。' },
    ],
